-- 009 飯田市オープンデータ「子育て施設」の4地区の施設を、市の CSV にそろえる。
-- このファイルは npm run childcare:sql で作る。手で編集しない（手順は docs/009_ingest-city-opendata.md）
-- CSV：https://www.city.iida.lg.jp/uploaded/attachment/72372.csv

update public.data_sources set
  credit_text = '出典：飯田市（https://www.city.iida.lg.jp/soshiki/168/opendata.html）、PDL1.0（https://www.digital.go.jp/resources/open_data/public_data_license_v1.0）（2026年10月24日に利用）。「子育て施設」（飯田市）（https://www.city.iida.lg.jp/soshiki/168/opendata.html）を加工して作成（4地区の施設を抜き出し、同じ場所の行をまとめた）',
  period_label = '2024年11月5日更新',
  checked_on = '2026-10-24'::date
where id = 'iida_childcare';

delete from public.facilities where source_id = 'iida_childcare';
